     9	const PROCESSING_FEE = 5;
    10	const FIRST_INSURANCE_SURCHARGE = 0.1;
    11	
    12	// Components (e.g. runes, moonstones) share one price-list tariff.
    13	const COMPONENT_BASE_PREMIUM = 25;
    14	
    15	const BASE_PREMIUMS: Record<string, number> = {
    16	  sword: 100,
    17	  amulet: 60,
    18	  staff: 80,
    19	  potion: 40,
    20	  rune: COMPONENT_BASE_PREMIUM,
    21	  moonstone: COMPONENT_BASE_PREMIUM,
    22	};
    23	
    24	const PREMIUM_PRECISION = 1e-9;
    25	
    26	function roundUpInMHPCOFavor(amount: number): number {
    27	  return Math.ceil(amount - PREMIUM_PRECISION);
    28	}
    29	
    30	function policyBasePremium(items: Item[]): number {
    31	  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
    32	}
    33	
    34	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
    35	  const basePremium = policyBasePremium(items);
    36	  const modifiedPremium = basePremium + basePremium * FIRST_INSURANCE_SURCHARGE;
    37	  return roundUpInMHPCOFavor(modifiedPremium + PROCESSING_FEE);
    38	}
